      "pins": ["REG2.1", "FCC1.11", "FCC1.27", "FCC1.50", "FCC1.75", "FCC1.100", "NAVC1.19", "NAVC1.32", "NAVC1.48", "NAVC1.64"],
      "nets": ["+3.3V", "+3V3", "unconnected-(FCC1-VDD-Pad11)", "unconnected-(FCC1-VDD-Pad27)", "unconnected-(FCC1-VDD-Pad50)", "unconnected-(FCC1-VDD-Pad75)", "unconnected-(FCC1-VDD-Pad100)", "unconnected-(NAVC1-VDD-Pad19)", "unconnected-(NAVC1-VDD-Pad32)", "unconnected-(NAVC1-VDD-Pad48)", "unconnected-(NAVC1-VDD-Pad64)"],
      "observed": "REG2.1 and REG2.2 are on +3.3V, but the MCU VDD pins are listed as unconnected. The separate +3V3 net has no connection to REG2.",
      "expected": "The regulated 3.3 V rail should power the VDD pins of both MCUs, as specified for the MCU and sensor supply.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"1\") (name \"+3.3V\") ... (node (ref \"REG2\") (pin \"1\") ... (node (ref \"REG2\") (pin \"2\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"2\") (name \"+3V3\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"216\") (name \"unconnected-(FCC1-VDD-Pad11)\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"276\") (name \"unconnected-(NAVC1-VDD-Pad19)\")"
        },
        {
          "source": "spec",
          "quote": "3.3 V LDO, fed from the 5 V rail, produces 3V3 for \"MCUs and Sensors\""
        }
      ],
      "impact": "Neither MCU has its VDD pins connected to the regulated supply in the netlist, so the flight-control and navigation computers cannot operate as intended.",
      "confidence": 0.99
    },
    {
      "category": "bridged_nets",
      "components": ["FCC1", "UART3_FCC1", "C13"],
      "pins": ["FCC1.48", "FCC1.73", "UART3_FCC1.3", "UART3_FCC1.4"],
      "nets": ["UART3_TX_FCC", "UART3_RX_FCC", "unconnected-(C13-Pad1)"],
      "observed": "Both FCC1 pins identified as VCAP are connected to the UART3 connector nets; C13, a 2.2 uF capacitor, is unconnected.",
      "expected": "The STM32H753 VCAP pins should have their required capacitor connections to ground, not be used as UART signals.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"144\") (name \"UART3_RX_FCC\") ... (node (ref \"FCC1\") (pin \"73\") (pinfunction \"VCAP\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"146\") (name \"UART3_TX_FCC\") ... (node (ref \"FCC1\") (pin \"48\") (pinfunction \"VCAP\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"166\") (name \"unconnected-(C13-Pad1)\")"
        },
        {
          "source": "netlist",
          "quote": "(pin (num \"48\") (name \"VCAP\") (type \"power_out\"))"
        }
      ],
      "impact": "The H753's internal regulator decoupling is missing, while its VCAP pins are exposed to UART signals; this can prevent reliable MCU operation and may risk damage.",
      "confidence": 0.99
    },
    {
      "category": "open_connection",
      "components": ["HSE1", "HSE2", "FCC1", "NAVC1"],
      "pins": ["FCC1.5", "FCC1.37", "FCC1.12", "FCC1.13", "NAVC1.5", "NAVC1.6"],
      "nets": ["HSE_IN_FCC", "HSE_OUT_FCC", "HSE_IN_NAVC", "HSE_OUT_NAVC", "Net-(FCC1-PH0)", "VREF+_FCC"],
      "observed": "FCC1's crystal nets connect to pins 5 and 37 (PE6 and PE7), not its PH0/PH1 pins. NAVC1's crystal nets have no MCU pin nodes; its PH0 and PH1 pins instead connect to C37 and C38.",
      "expected": "Each MCU's 25 MHz HSE crystal should connect between its HSE input and output pins (PH0/PH1), with the associated load capacitors.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"31\") (name \"HSE_IN_FCC\") ... (node (ref \"FCC1\") (pin \"5\") (pinfunction \"PE6\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"33\") (name \"HSE_OUT_FCC\") ... (node (ref \"FCC1\") (pin \"37\") (pinfunction \"PE7\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"32\") (name \"HSE_IN_NAVC\") ... (node (ref \"HSE2\") (pin \"1\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"34\") (name \"HSE_OUT_NAVC\") ... (node (ref \"R32\") (pin \"1\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"89\") (name \"Net-(NAVC1-PH0)\") ... (node (ref \"C37\") (pin \"1\")"
        }
      ],
      "impact": "The external high-speed clock is not connected to the HSE pins of either MCU, so the intended crystal clock cannot be used; the FCC crystal is routed to unrelated GPIOs.",
      "confidence": 0.97
    }
  ],
  "summary": "Anomalies are present: the MCU supply pins are unconnected to the regulated 3.3 V rail, the H753 VCAP pins are assigned to UART nets instead of required decoupling, and the HSE crystals are not connected to the MCUs' HSE pins."
}

